function HomepageEditorialSection(){
 const [items,setItems]=useState<any[]>([]);
 const [loading,setLoading]=useState(true);
 useEffect(()=>{let active=true;api('/content?limit=12').then(data=>{if(active)setItems((Array.isArray(data)?data:[]).filter((x:any)=>x.is_featured).slice(0,3))}).catch(()=>{if(active)setItems([])}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[]);
 if(loading||!items.length)return null;
 return <section className="section wrap homepage-editorial"><div className="section-heading"><div><Eyebrow>THE ELSEWHERE JOURNAL</Eyebrow><h2>A little inspiration goes a long way.</h2><p>Thoughtful reads and local discoveries for the journey ahead.</p></div><Link className="arrow-link" to="/stories">Explore the journal <ArrowUpRight/></Link></div><div className="homepage-editorial-grid">{items.map((x:any)=><Link className="homepage-editorial-card" to={`/stories/${x.slug}`} key={x.id}><div className="homepage-editorial-image">{x.image_url?<img src={x.image_url} alt={x.title}/>:<span>ELSEWHERE JOURNAL</span>}</div><div className="homepage-editorial-copy"><Eyebrow>{x.content_type}{x.destination_name?` · ${x.destination_name}`:''}</Eyebrow><h3>{x.title}</h3><p>{x.summary}</p><span className="text-link">Read the story <ArrowRight size={15}/></span></div></Link>)}</div></section>
}
