 useEffect(()=>{let active=true;api(`/shared-itineraries/${encodeURIComponent(token||'')}`).then(data=>{if(active)T(data)}).catch(e=>{if(active)E(e instanceof Error?e.message:'This shared trip is unavailable.')}).finally(()=>{if(active)L(false)});return()=>{active=false}},[token]);
