 return <main className="page wrap shared-trip-page"><div className="page-intro"><Eyebrow>AN ELSEWHERE JOURNEY · SHARED WITH YOU</Eyebrow><h1>{trip.title}</h1><p>{trip.origin} to {trip.destination} · {trip.days} days · {trip.travellers} travellers</p></div><section className="shared-trip-stops">{Array.isArray(trip.stops)&&trip.stops.length?trip.stops.map((stop:any,index:number)=><article className="timeline-stop" key={stop.id||index}><span className="timeline-dot"/><div><small>DAY {stop.day||index+1}</small><h2>{stop.title}</h2>{stop.detail&&<p>{stop.detail}</p>}</div></article>):<p className="empty-state">No itinerary stops were shared.</p>}</section><p className="disclaimer">Read-only shared itinerary. Confirm dates, routes, prices and opening hours before travel.</p><Link className="button" to="/planner">Plan your own journey <ArrowRight/></Link></main>
