 function downloadExpenseCsv(){const csvCell=(value:any)=>{const text=String(value??'');return /[",\\n\\r]/.test(text)?`"${text.replace(/"/g,'""')}"`:text};const rows:any[][]=[['Elsewhere trip expense report'],['Itinerary',plan?.title||`${origin} to ${destination}`],['Currency',budgetParts.currency||'INR'],['Planned budget',budgetTotal],['Actual spending',actualTotal],['Remaining / over budget',budgetVariance],[],['Category','Planned','Actual','Difference']];expenseCategories.forEach(key=>rows.push([expenseLabel(key),Number(budgetParts[key]||0),actualByCategory(key),Number(budgetParts[key]||0)-actualByCategory(key)]));rows.push([],['Date','Category','Amount','Note']);actualExpenses.forEach(item=>rows.push([item.date,expenseLabel(item.category),item.amount,item.note||'']));const content='\\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\\r\\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`elsewhere-expenses-${plan?.id||'trip'}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}

