 async function submit(e:FormEvent){e.preventDefault();S(true);E('');try{const result=await api('/itineraries',{method:'POST',body:JSON.stringify({origin,destination,days,travellers,interests:interest,estimated_budget:Number(budget.replace(/[^0-9]/g,''))})});P(result);SD(false);const returned=Array.isArray(result?.stops)?result.stops:[];ST(returned.length?returned:Array.from({length:days},(_,i)=>({day:i+1,title:i===0?'Arrival & local discovery':i===days-1?'A slower return journey':'Explore nearby highlights',detail:'Suggested planning prompt — add a place from the destination suggestions and confirm travel times before departure.'})));}catch(err){E(err instanceof Error?err.message:'Could not save the itinerary. A local draft is shown instead.');const draft={title:`${origin} to ${destination}`,days};P(draft);ST(Array.from({length:days},(_,i)=>({day:i+1,title:i===0?'Arrival & local discovery':i===days-1?'A slower return journey':'Explore nearby highlights',detail:'Draft idea — verify routes, opening hours and travel time before travelling.'})));}finally{S(false)}}
