 const download=async(id:string,name:string,kind:"invoice"|"voucher")=>{try{const token=localStorage.getItem("elsewhere_token")||localStorage.getItem("access_token")||"";const path=kind==="invoice"?"invoice":"voucher";const res=await fetch(`/api/v1/tour-package-${path}s/${id}/pdf`,{headers:token?{Authorization:`Bearer ${token}`}:{}});if(!res.ok)throw new Error(`${kind==="invoice"?"Invoice":"Voucher"} download failed`);const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`${name}${kind==="voucher"?"-travel-voucher":""}.pdf`;a.click();URL.revokeObjectURL(url)}catch(e:any){ErrorMsg(e.message||`Could not download ${kind}`)}};
